import numpy as np
import pandas as pd
from joblib import Parallel, delayed

def calculate_rms(values):
    squared_values = values ** 2
    mean_squared_value = squared_values.mean()
    rms_value = np.sqrt(mean_squared_value)
    return rms_value

def process_chunk(chunk):
    return calculate_rms(chunk['MLII'])

def calculate_rms_parallel(df, record_id, signal, chunk_size=1000):
    try:
        record_df = df[df['record_id'] == record_id]
        if record_df.empty:
            raise ValueError(f"No data found for record_id {record_id}")

        chunks = [record_df[i:i+chunk_size] for i in range(0, len(record_df), chunk_size)]
        rms_values = Parallel(n_jobs=-1)(delayed(process_chunk)(chunk) for chunk in chunks)
        overall_rms = np.sqrt(np.mean([rms**2 for rms in rms_values]))
        return overall_rms
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

result = calculate_rms_parallel(df, 106, 'MLII')
